import React, { Component } from 'react'
import {Dimensions, Image, Text, TouchableWithoutFeedback, View, BackHandler} from 'react-native'
import styles from './TestStyles';
import SnapCarousel from 'react-native-snap-carousel';
import {NavigationActions, StackActions} from 'react-navigation';
import axios from "axios";

const screen = Dimensions.get('window');


class createTest extends Component {

  static navigationOptions = ({ navigation }) => ({
    title: 'Create Test',
    header: null
  })

   constructor() {
    super();
    this.state = {
      duration: 30,
      goalImage: [
        {
          name: 'CBSE',
          photo: 'data:image/png;base64,',
        },
        {
          name: 'JEE-MAINS',
          photo: 'data:image/png;base64,',
        },
        {
          name: 'JEE-ADVANCED',
          photo: 'data:image/png;base64,',
        },
      ],
      subjectsImage: [
        {
          name: 'Physics',
          photo: 'data:image/png;base64,',
        },
        {
          name: 'Chemistry',
          photo: 'data:image/png;base64,',
        },
        {
          name: 'Mathematics',
          photo: 'data:image/png;base64,',
        },
        {
          name: 'Science',
          photo: 'data:image/png;base64,'
        }
      ],
      goal: [],
      subjects: [],
      selectedGoal: null,
      selectedSubject: null,
      selectedSubjectName: '',
      selectedGoalName: '',
    }
    this.handleBackButton = this.handleBackButton.bind(this);
  }

  handleBackButton() {
    
    this.props.navigation.dispatch(StackActions.popToTop());
    this.props.navigation.navigate('Tabs', {}, NavigationActions.navigate({ routeName: 'Tabs' }));
    return true;
  }

  componentWillUnmount() {
    BackHandler.removeEventListener('hardwareBackPress', this.handleBackButton);
  }

  componentDidMount() {
    BackHandler.addEventListener('hardwareBackPress', this.handleBackButton);
    axios.get('https://classcast-198812.appspot.com/coursedata/testGoalAndSubjectList')
      .then((response) => {
        this.setState({goal: response.data.goal});
        this.setState({subjects: response.data.subjects});
        this.setState({ selectedGoal: response.data.goal[0]['index'],
                        selectedSubject: response.data.subjects[0]['index'],
                        selectedGoalName: response.data.goal[0]['name'],
                        selectedSubjectName: response.data.subjects[0]['name']
         });
        console.log("sniuasa: "+JSON.stringify(response.data));
        console.log("sniuasa12"+ JSON.stringify(response.data.subjects[0]['index']))
      })
  }

  _renderItemGoal = ({item, index}) => {
    return (
      <View style={styles.goalCardWrapper}>
        <TouchableWithoutFeedback

          onPress={() => {
            this.setState({
              selectedGoal: item.index,
            });

            const goal = !index ? 'CBSE': index === 1? 'JEE MAIN': 'JEE ADVANCED';

            this.setState({selectedGoalName: this.state.goal[index].name});
          }}
        >
          <View
            style={
              this.state.selectedGoal !== item.index
                ? styles.goalCard
                : [styles.goalCard, {transform: [{scaleX: 1.05}, {scaleY: 1.05}]}]
            }
          >
            {
              this.state.selectedGoal === item.index
              && <View style={styles.selectedCardIconContainer}>
                <Image
                  style={styles.selectedCardIcon}
                  source={{uri: 'data:image/png;base64,'}}
                />
              </View>
            }
            <Image
              style={styles.goalImage}
              resizeMode={'contain'}
              source={{uri: this.state.goalImage[item.index].photo}}
            />
            <Text style={styles.goalName}>
              {item.name}
            </Text>
          </View>
        </TouchableWithoutFeedback>
      </View>
    );
  };
  _renderItemSubject = ({item, index}) => {
    return (
      <View style={styles.goalCardWrapper}>
        <TouchableWithoutFeedback
          onPress={() => {
            this.setState({
              selectedSubject: item.index,
            });
            const sub = !index? 'p': index === 1? 'c': 'm';
            
            this.setState({selectedSubjectName: this.state.subjects[index].name});
          }}
        >
          <View
            style={
              this.state.selectedSubject !== item.index
                ? styles.goalCard
                : [styles.goalCard, {transform: [{scaleX: 1.05}, {scaleY: 1.05}]}]
            }
          >
            {
              this.state.selectedSubject === item.index
              && <View style={styles.selectedCardIconContainer}>
                <Image
                  style={styles.selectedCardIcon}
                  source={{uri: 'data:image/png;base64,'}}
                />
              </View>
            }
            <Image
              style={styles.goalImage}
              resizeMode={'contain'}
              source={{uri: this.state.subjectsImage[item.index].photo}}
            />
            <Text style={styles.goalName}>
              {item.name}
            </Text>
          </View>
        </TouchableWithoutFeedback>
      </View>
    );
  }

   render() {
    console.log("ansanadskjaL : "+this.state.selectedSubject);
    return (
      <View style={styles.container}>
        <View style={styles.durationContainer}>
          <Text style={styles.sectionTitle}>Duration</Text>
          <View style={styles.toggleWrapper}>
            <TouchableWithoutFeedback
              onPress={() => {
                this.setState({duration: 30});
              }}
            >
              <View style={
                this.state.duration === 30
                  ? [styles.durationToggle, styles.activeToggle]
                  : styles.durationToggle
              }>
                {
                  this.state.duration === 30
                  && <Image
                    style={{
                      position: 'absolute',
                      top: 0,
                      height: '100%',
                      width: '100%',
                    }}
                    source={{uri: 'data:image/png;base64,'}}
                  />
                }
                <Text style={
                  this.state.duration === 30
                    ? [styles.durationToggleText, styles.activeToggleText]
                    : styles.durationToggleText
                }>30 MINUTES</Text>
              </View>
            </TouchableWithoutFeedback>
            <TouchableWithoutFeedback
              onPress={() => {
                this.setState({duration: 60});
              }}
            >
              <View style={
                this.state.duration === 60
                  ? [styles.durationToggle, styles.activeToggle]
                  : styles.durationToggle
              }>
                {
                  this.state.duration === 60
                  && <Image
                    style={{
                      position: 'absolute',
                      top: 0,
                      height: '100%',
                      width: '100%',
                    }}
                    source={{uri: 'data:image/png;base64,'}}
                  />
                }
                <Text style={
                  this.state.duration === 60
                    ? [styles.durationToggleText, styles.activeToggleText]
                    : styles.durationToggleText
                }>1 HOUR</Text>
              </View>
            </TouchableWithoutFeedback>
          </View>
        </View>
        <View style={styles.goalContainer}>
          <Text style={styles.sectionTitle}>Goal</Text>
          <View style={styles.goalWrapper}>
            <SnapCarousel
              // ref={(c) => { this._carousel = c; }}
              data={this.state.goal}
              renderItem={this._renderItemGoal.bind(this)}
              sliderWidth={screen.width}
              itemWidth={0.45 * screen.width}
              enableMomentum={true}
              enableSnap={false}
              inactiveSlideScale={0.9}
              inactiveSlideOpacity={1}
              autoplayDelay={100}
              autoplayInterval={1000}
              firstItem={0}
              activeSlideAlignment= {'center'}
              onSnapToItem={index => {
                this.setState({selectedGoal: index})
              }}
            />
          </View>
        </View>
        <View style={[styles.goalContainer, {marginTop: 0}]}>
          <Text style={styles.sectionTitle}>Subject</Text>
          <View style={styles.goalWrapper}>
            <SnapCarousel
              // ref={(c) => { this._carousel = c; }}
              data={this.state.subjects}
              renderItem={this._renderItemSubject.bind(this)}
              sliderWidth={screen.width}
              itemWidth={0.45 * screen.width}
              enableMomentum={true}
              enableSnap={false}
              inactiveSlideScale={0.9}
              inactiveSlideOpacity={1}
              autoplayDelay={100}
              autoplayInterval={1000}
              firstItem={0}
              activeSlideAlignment= {'center'}
              onSnapToItem={index => {
                this.setState({selectedSubject: index})
              }}
            />
          </View>
        </View>

        <TouchableWithoutFeedback
          onPress={() => {
            const navigateAction = NavigationActions.navigate({
              routeName: 'topic',
              params: {
                duration: this.state.duration,
                goal: this.state.selectedGoalName,
                goalIndex: this.state.selectedGoal,
                subject: this.state.selectedSubjectName,
                subjectIndex: this.state.selectedSubject,
              },
            });
            this.props.navigation.dispatch(navigateAction); 
          }}
        >
          <View style={[styles.nextPage, {left: 0.455 * screen.width}]}>
            <Image
              style={styles.nextPageIcon}
              resizeMode={'contain'}
              source={{uri: 'data:image/png;base64,'}}
            />
          </View>
        </TouchableWithoutFeedback>

      </View>
    )
  }

}

export default createTest
